-- Nội dung tiếng Anh cho 117 task trong thư viện (dịch tự động, đã kiểm tra khớp code/shape).
update tasks set title_en = 'Understanding Stress', description_en = 'Helps you understand the nature of stress, fatigue, and even loss — where they come from, and why some stress is actually a normal part of life.', steps_en = '["1. Spend 5 minutes noticing your body and how you''re feeling right now.","2. Write down what''s stressing you out.","3. Identify whether the stress is coming from work, family, money, health, or a relationship.","4. Remind yourself that stress is a signal to adjust something, not proof that you''re weak.","5. Pick one small action you can take today to ease the pressure."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps redirect your attention away from anxiety triggers"]}'::jsonb where code = '1.1';
update tasks set title_en = 'Soak Up Some Sunshine', description_en = 'Take a little time to soak up the sunshine — it''s great for both your skin and your mood.', steps_en = '["1. Pick a time with gentle sun, ideally in the morning.","2. Head out to a balcony, yard, park, or anywhere with natural light.","3. Stand or sit and relax for 5–15 minutes.","4. Feel the warmth on your skin and breathe slowly.","5. Finish with the thought: \"I''m giving my body a little more energy.\""]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps redirect your attention away from anxiety triggers"]}'::jsonb where code = '1.1-b';
update tasks set title_en = 'Watch a Sunrise or Sunset Alone', description_en = 'Spend a few quiet minutes watching a sunrise or sunset, paying attention to the colors and your breathing to let your mind settle.', steps_en = '["1. Choose a safe, quiet spot to watch the sky.","2. Put your phone down, or just use it to snap one photo.","3. Watch the colors, the light, and the clouds drifting by.","4. Breathe slowly and let your thoughts pass naturally.","5. Write down one feeling you noticed once you''re done watching."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps redirect your attention away from anxiety triggers"]}'::jsonb where code = '1.11';
update tasks set title_en = 'Unfollow the Noise', description_en = 'Review and unfollow accounts or content that feel negative or draining, to create a healthier digital space for yourself.', steps_en = '["1. Open the social media apps or news sources you check most often.","2. Notice which accounts leave you stressed, comparing yourself, angry, or drained.","3. Unfollow, mute, turn off notifications, or unfriend if you need to.","4. Replace them with sources that feel healthy, educational, or inspiring.","5. Notice how much lighter you feel after cleaning up your digital space."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps redirect your attention away from anxiety triggers"]}'::jsonb where code = '1.12';
update tasks set title_en = 'Slow Down and Drink More Water (Mindful Drinking Game)', description_en = 'Drinking more water helps speed up your metabolism.', steps_en = '["1. Right after you wake up, prepare a glass of water.","2. Hold the glass with both hands and notice its temperature.","3. Take small sips, without rushing.","4. Notice the feeling of the water moving down your throat and your body waking up.","5. Set a goal to drink more water today by keeping a bottle within reach."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Hydrates your brain cells, easing tension headaches","Triggers the swallowing reflex, which helps calm your vagus nerve","A simple, effective way to practice grounding"]}'::jsonb where code = '1.13';
update tasks set title_en = 'Cut Back on Smoking and Drinking', description_en = 'Gradually reduce smoking and drinking, and choose a healthier habit to replace them so your body and mind feel steadier.', steps_en = '["1. Note how often you currently smoke or drink in a day or a week.","2. Choose a small, realistic reduction — nothing extreme.","3. Identify the situations that make you want to smoke or drink.","4. Swap it out with water, a walk, sugar-free gum, deep breathing, or calling someone for support.","5. If the dependence is severe or you have withdrawal symptoms, please reach out to a medical professional."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps redirect your attention away from anxiety triggers"]}'::jsonb where code = '1.14';
update tasks set title_en = 'Free Dance Challenge', description_en = 'Put on a fun song and let yourself dance freely for 3–5 minutes.', steps_en = '["1. Choose a song that makes you want to move.","2. Stand somewhere safe with enough space.","3. Dance freely to the beat — it doesn''t need to look good or be the \"right\" moves.","4. Let your body release tension through movement.","5. Stop, place your hand on your chest, and feel your heart beating with life."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers your heart rate and syncs your brainwaves into a relaxed Alpha state","Stimulates the brain''s cortex to release dopamine","Reduces anxiety noticeably more than sitting in passive silence"]}'::jsonb where code = '1.15';
update tasks set title_en = 'Play With a Pet', description_en = 'Play with your pet, or spend time with a puppy or kitten.', steps_en = '["1. Choose a familiar, safe pet or animal.","2. Spend 5–15 minutes petting, playing, or feeding them.","3. Focus on your breathing, their fur, their eyes, or their movements.","4. Don''t force the animal to interact if they don''t want to.","5. Notice how much calmer you feel after connecting with them."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps redirect your attention away from anxiety triggers"]}'::jsonb where code = '1.16';
update tasks set title_en = 'Take the Stairs (Stair Challenge)', description_en = 'Change up your movement — instead of the elevator or escalator, take the stairs.', steps_en = '["1. Choose a flight of stairs that''s manageable and safe for you.","2. Walk at a steady pace, holding the railing if needed.","3. Focus on each step and your breathing.","4. Stop if you feel dizzy, chest pain, or overly tired.","5. Give yourself credit for the chance to move your body."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Releases endorphins, easing pain and creating a sense of uplift","Improves blood flow to the brain, making you feel clearer-headed","Burns off excess adrenaline that causes restlessness"]}'::jsonb where code = '1.17';
update tasks set title_en = 'Gaze at the Sea', description_en = 'Look out at the sea, or take in a view from a mountaintop. You can walk along the beach, feel the waves against your feet, and walk barefoot in the sand. On a mountain, you could even let out a loud shout.', steps_en = '["1. Choose a beach, or an image/sound of the sea if you can''t go in person.","2. Sit or stand somewhere safe.","3. Watch the waves rise and fall, and listen to the sound of the sea.","4. Imagine your stress being pulled out to sea like the tide.","5. Write down one thing you''d like the sea to carry away."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps redirect your attention away from anxiety triggers"]}'::jsonb where code = '1.18';
update tasks set title_en = 'Tidy Up', description_en = 'Tidy your home or workspace, simplify things, and let go of what you no longer need. This frees up your eyes, and then your mind — helping you feel more comfortable and focused. Less is more.', steps_en = '["1. Choose one small area, like a desk, bed, bag, or corner of a room.","2. Throw away trash and things you no longer need.","3. Group similar items back together.","4. Wipe down surfaces or create one clear, pleasant space.","5. Stand back, look at the space, and notice a gentle sense of control."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps redirect your attention away from anxiety triggers"]}'::jsonb where code = '1.19';
update tasks set title_en = 'Get Enough Sleep', description_en = 'Sleeping 7–9 hours a night helps improve your mood and strengthens focus and decision-making (Walker, 2017).', steps_en = '["1. Pick a fairly consistent bedtime and wake-up time.","2. Turn off electronic devices before bed.","3. Dim the lights, reduce noise, and set up a comfortable space.","4. If you can''t fall asleep, try slow breathing or relaxing your body instead of forcing yourself to sleep.","5. Note how your sleep felt the next morning."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Restores energy to your cells and clears out mental ''waste''","Rebalances the stress hormones cortisol and adrenaline","Strengthens memory and problem-solving ability"]}'::jsonb where code = '1.2';
update tasks set title_en = 'Deep Focus Work', description_en = 'Give yourself even just 10–30 minutes to think deeply and work through something difficult that needs real focus. This can help you feel a sense of high performance and release stress through deep concentration. Try methods like GTD (Getting Things Done) to manage your work more effectively and ease your stress.', steps_en = '["1. Choose the most important task of your day.","2. Turn off notifications and remove distractions.","3. Set a focus window of 25–45 minutes.","4. Work on only that one task during that time.","5. Once you''re done, take a short break and acknowledge your progress."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Thickens the prefrontal cortex, improving emotional regulation","Shrinks the amygdala, the brain region linked to anxiety","Increases your attention span"]}'::jsonb where code = '1.2-b';
update tasks set title_en = 'Hang Up a Motivating Photo', description_en = 'Hang up a photo of someone you love, or a motivating picture that only you know the meaning behind — it can help you feel that things are better, that you''re still lucky, and that beautiful feelings still exist for you.', steps_en = '["1. Choose an image that reminds you of your goals, someone you love, or a better version of yourself.","2. Print it or place it somewhere you''ll see it easily.","3. Write a short reminder next to it.","4. Each day, look at it for 30 seconds and breathe slowly.","5. Ask yourself: \"What small step can I take today?\""]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps redirect your attention away from anxiety triggers"]}'::jsonb where code = '1.21';
update tasks set title_en = 'Get Moving', description_en = 'Punch a pillow or a punching bag, or do some push-ups.', steps_en = '["1. Choose a form of movement that suits your energy, like walking, stretching, hitting a punching bag, cycling, or cleaning.","2. Warm up gently for 1–2 minutes.","3. Move for a length of time that fits your fitness level.","4. Pay attention to how your body feels rather than any performance goal.","5. Stop, drink some water, and notice how your stress level has shifted."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Releases endorphins, easing pain and creating a sense of uplift","Improves blood flow to the brain, making you feel clearer-headed","Burns off excess adrenaline that causes restlessness"]}'::jsonb where code = '1.22';
update tasks set title_en = 'Sauna Session', description_en = 'If you can''t move around much, try a sauna — sweating it out can help you release stress.', steps_en = '["1. Only use a sauna if your health allows it and there''s no medical reason to avoid it.","2. Drink water before your sauna session.","3. Keep it short — don''t force yourself to endure too much heat.","4. Leave the sauna if you feel dizzy, short of breath, or notice an irregular heartbeat.","5. Rest, rehydrate, and feel your body relax."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps redirect your attention away from anxiety triggers"]}'::jsonb where code = '1.23';
update tasks set title_en = 'Massage', description_en = 'Grab a massage tool like a massage gun, a tennis ball, or a golf ball.', steps_en = '["1. Choose a tense area of your body, like your shoulders, neck, arms, or legs.","2. Use your hands, a tennis ball, a massage tool, or ask someone you trust to help.","3. Massage gently, without pressing too hard.","4. Breathe slowly as you let your muscles relax.","5. Notice which part of your body feels calmer now."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps redirect your attention away from anxiety triggers"]}'::jsonb where code = '1.24';
update tasks set title_en = 'A Positive Change in Appearance', description_en = 'Getting a haircut or making a positive change to your appearance can boost your confidence and change how others see you, too.', steps_en = '["1. Choose a small change, like a haircut, neater clothes, skincare, or a style refresh.","2. Do it because you want to care for yourself, not because you dislike yourself.","3. Stay within your budget and time.","4. Look at yourself with kind eyes.","5. Notice the fresh or more confident feeling afterward."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Rewires your brain in a positive direction (neuroplasticity)","Can reduce depressive symptoms by up to 30% with long-term practice","Boosts your body''s natural serotonin production"]}'::jsonb where code = '1.25';
update tasks set title_en = 'Shift Toward Healthier Eating', description_en = 'Foods rich in omega-3s (salmon, walnuts), magnesium (leafy greens), and vitamin B (eggs, whole grains) support brain function, reduce inflammation, and balance hormones. Try cutting back on red meat in favor of poultry or plant-based options. Avoid foods that spike your blood sugar (sweets, refined carbs) and too much salt. A daily square of dark chocolate can also help ease stress effectively.', steps_en = '["1. Notice one eating habit that''s been draining you.","2. Choose one small change, like adding vegetables, drinking more water, cutting back on sweets, or eating on time.","3. Don''t force yourself into an extreme diet.","4. Prepare a simple, balanced meal.","5. Notice how your body responds after eating."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Hydrates your brain cells, easing tension headaches","Triggers the swallowing reflex, which helps calm your vagus nerve","A simple, effective way to practice grounding"]}'::jsonb where code = '1.26';
update tasks set title_en = 'Sound Scavenger Hunt', description_en = 'Sit still and list 3 sounds you hear in your surroundings — birds singing, wind blowing, traffic passing.', steps_en = '["1. Sit still somewhere reasonably safe.","2. Close your eyes or let your gaze rest gently downward.","3. Find 5 sounds close to you.","4. Find 3 sounds further away.","5. Notice that you''re here in the present moment, without needing to chase every thought."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers your heart rate and syncs your brainwaves into a relaxed Alpha state","Stimulates the brain''s cortex to release dopamine","Reduces anxiety noticeably more than sitting in passive silence"]}'::jsonb where code = '1.27';
update tasks set title_en = 'Use a scented candle (natural) or flower scents', description_en = 'Using a scent can help you relax — it could simply be the smell of flowers, a scented candle, fermented yogurt, ripening rice fields, or plants and grass...', steps_en = '["1. Choose a candle, essential oil, or flower with a mild, safe scent.","2. Place it somewhere well-ventilated, away from anything flammable.","3. Breathe slowly and pay attention to the scent.","4. Let the scent become linked to a feeling of rest.","5. Extinguish the candle safely after use."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from anxiety triggers"]}'::jsonb where code = '1.28';
update tasks set title_en = 'Listen to a motivating song (Motivational Music Task)', description_en = 'Suggest a playlist of motivating music for the user.', steps_en = '["1. Choose a song that makes you feel more alive.","2. Listen to the whole song without doing anything else.","3. Notice the lyrics, the rhythm, or the emotions that come up.","4. If you feel like it, sing along or move gently.","5. Write down one line from the song that lifted you up."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from anxiety triggers"]}'::jsonb where code = '1.29';
update tasks set title_en = 'Check in with yourself before sleep and upon waking, before getting out of bed', description_en = 'Take a few minutes before sleep to ask yourself: What made you proud today, what did you accomplish today? What should you do, and what should you not have done?', steps_en = '["1. While lying in bed, place a hand on your chest or belly.","2. Ask yourself: \"What am I feeling right now?\"","3. Then ask: \"What''s the smallest thing I need right now?\"","4. Answer slowly, without judging yourself.","5. Choose one gentle action to start or end your day with."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Restores energy to your cells and clears out mental \"clutter\"","Helps rebalance stress hormones cortisol and adrenaline","Boosts memory and problem-solving ability"]}'::jsonb where code = '1.3';
update tasks set title_en = 'Pick a favorite quote (Pick a Positive Quote)', description_en = 'The app offers a range of uplifting quotes; pick the one you love most and write down why. It especially features the quote "This too shall pass." Or you can create your own saying.', steps_en = '["1. Find a saying that makes you feel calm, strong, or hopeful.","2. Write it down on paper or save it on your phone.","3. Read it slowly, three times.","4. Ask: \"What does this remind me of today?\"","5. Put the quote somewhere you''ll see it easily."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from anxiety triggers"]}'::jsonb where code = '1.3-b';
update tasks set title_en = 'Feel your feet (Grounding with Feet Awareness)', description_en = 'Guide the user to take off their shoes and feel the soles of their feet touching the ground for 2 minutes.', steps_en = '["1. Place both feet flat on the floor.","2. Notice the point of contact between your feet and the ground.","3. Gently press your toes into the floor, then release.","4. Breathe in slowly, and breathe out for a long, slow count.","5. Remind yourself: \"I am here, right now.\""]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from anxiety triggers"]}'::jsonb where code = '1.31';
update tasks set title_en = 'Ask yourself simple questions and answer slowly and honestly', description_en = 'Ask yourself questions like "Are these thoughts actually helping me?" Practicing this kind of self-awareness and honest self-check always helps clear away some of the mental clutter.', steps_en = '["1. Choose a quiet space.","2. Ask: \"What''s stressing me the most right now?\"","3. Then ask: \"What''s actually within my control?\"","4. Answer in short, honest sentences.","5. Choose one small step you can take right now."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from anxiety triggers"]}'::jsonb where code = '1.32';
update tasks set title_en = 'Make a list of "the 5 most important things in your life"', description_en = 'My list is: Health, Family, Career, Social relationships, Personal passions and joy. What about you? Set everything else aside for now. List 20 things that fall within these areas, and 20 to 30 things that don''t.', steps_en = '["1. Grab paper or open a notes app.","2. Write down the 5 things, people, or values that matter most to you.","3. Arrange them by your current priorities.","4. Notice which one you''re actually spending the most time on.","5. Choose one small action to bring you back to what truly matters."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from anxiety triggers"]}'::jsonb where code = '1.33';
update tasks set title_en = 'Make a "3 things I''m grateful for" list (Gratitude List Game)', description_en = 'Ask the user to list 3 things they feel grateful for today. Be grateful even for enemies and people who weren''t kind to you — they teach you to appreciate everyone else, the people who still smile at you with warmth and trust every day.', steps_en = '["1. Pause for 3 minutes.","2. Write down 3 things you''re grateful for today, no matter how small.","3. For each one, write why it matters to you.","4. Read them back slowly.","5. Notice any warmth or lightness in your body."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Reshapes the brain (neuroplasticity) in a positive direction","Can reduce depressive symptoms by up to 30% with long-term practice","Boosts natural serotonin production"]}'::jsonb where code = '1.34';
update tasks set title_en = 'Do a simple exercise routine', description_en = 'Do simple movements or self-massage, like stretching your shoulders or massaging your eyes.', steps_en = '["1. Choose a gentle exercise like shoulder rolls, stretching, light squats, or marching in place.","2. Warm up slowly for 1 minute.","3. Move for 5–10 minutes, at your own pace.","4. Don''t push your body past its limits.","5. Finish with slow breathing and a glass of water."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Releases endorphins that ease pain and lift your mood","Improves blood flow to the brain, helping you feel clearer","Burns off excess adrenaline that causes restlessness"]}'::jsonb where code = '1.35';
update tasks set title_en = 'Social interaction, level 1', description_en = 'Ask the user to reach out with kindness, warmth, and helpfulness — to society, a club, a group, or a stranger. Give, and you''ll receive.', steps_en = '["1. Choose one safe person for a brief interaction.","2. Send a friendly check-in message or a warm emoji.","3. Don''t expect them to reply right away.","4. If they respond, reply kindly and sincerely.","5. Notice that you''ve opened a small door to connection."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from anxiety triggers"]}'::jsonb where code = '1.37';
update tasks set title_en = 'Talk to yourself: be kind to yourself — talking with the inner child within you helps that child heal, grow stronger, and become more resilient.', description_en = 'Speak to yourself with kind words, listen to your inner needs, and encourage yourself the way you would a close friend.', steps_en = '["1. Sit somewhere private and place a hand on your chest.","2. Picture the young part of you inside that needs to be heard.","3. Speak to that part gently: \"I''m here with you.\"","4. Write down what that inner child is afraid of, sad about, or needs.","5. End with a small promise: \"I''ll take care of you, one step at a time.\""]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from anxiety triggers"]}'::jsonb where code = '1.38';
update tasks set title_en = 'Behave with grace: practice being polite and considerate toward everyone, starting with your family. Recognize your present worries, write them down, and look at them clearly.', description_en = 'Practice polite, caring communication with others; write down your current worries and think through what you can actually control.', steps_en = '["1. Notice a situation where you tend to react quickly.","2. Write your main worry down on paper.","3. Sort out what''s fact from what''s assumption.","4. Choose a response that''s polite, clear, and respectful.","5. Notice how it feels to slow down and respond with more care."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Raises oxytocin levels (the bonding hormone that lowers stress)","Reduces feelings of loneliness and low mood","Boosts motivation and self-worth through giving to others"]}'::jsonb where code = '1.39';
update tasks set title_en = 'List out the things you do that make you feel proud of yourself', description_en = 'No matter how small, list the abilities and accomplishments you recognize in yourself and feel proud of. It could be having a group of true friends, having a skill few others have, solving a tricky problem, or simply an act of kindness toward someone else. This gives you a strong emotional anchor — a reminder that you are a good person who deserves happiness.', steps_en = '["1. Grab paper or open a notes app.","2. Write down at least 5 things you''ve accomplished, no matter how small.","3. Don''t compare them to anyone else''s achievements.","4. Read them back and recognize the effort behind each one.","5. Pick one to remind yourself: \"I''ve made it through before.\""]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Reshapes the brain (neuroplasticity) in a positive direction","Can reduce depressive symptoms by up to 30% with long-term practice","Boosts natural serotonin production"]}'::jsonb where code = '1.4';
update tasks set title_en = 'Observe a familiar object (Mindful Observation Task)', description_en = 'Choose an object at home (a plant, a lamp, a painting) and focus on observing it closely for 2–3 minutes.', steps_en = '["1. Choose something nearby, like a pen, a cup, a leaf, or your keys.","2. Observe its color, shape, texture, and weight.","3. Touch it and describe how it feels in words.","4. If your mind wanders, gently bring it back to the object.","5. Finish with one deep breath."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from anxiety triggers"]}'::jsonb where code = '1.4-b';
update tasks set title_en = 'Make a "3 most valuable things in life" list (Kindness List Game)', description_en = 'Ask the user to list 3 kind things they did today.', steps_en = '["1. Write down the 3 core values that matter most to you.","2. Describe each value in one short sentence.","3. Ask yourself whether you''re living close to or far from that value.","4. Choose one small action to move closer to it.","5. Note how it feels to have this sense of direction after the exercise."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from anxiety triggers"]}'::jsonb where code = '1.44';
update tasks set title_en = 'Make a "3 achievements I''m proud of" list (Kindness List Game)', description_en = 'Ask the user to list 3 things/values/achievements they''re proud of, no matter how small.', steps_en = '["1. Recall 3 things you did that matched your own values.","2. Write each one down specifically, not in general terms.","3. Note the effort you put into each one.","4. Let yourself feel proud, in a healthy way.","5. Choose one value you want to keep living by."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Reshapes the brain (neuroplasticity) in a positive direction","Can reduce depressive symptoms by up to 30% with long-term practice","Boosts natural serotonin production"]}'::jsonb where code = '1.45';
update tasks set title_en = 'Make a "3 kind things today" list (Kindness List Game)', description_en = 'Ask the user to list 3 kind things they did today.', steps_en = '["1. Look back over your day.","2. Write down 3 kind things you did, received, or witnessed.","3. Don''t overlook small ones, like a smile, letting someone go first, or asking how someone''s doing.","4. Notice that kindness is still there, all around you.","5. Choose one small kind act for tomorrow."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from anxiety triggers"]}'::jsonb where code = '1.46';
update tasks set title_en = 'Listen to music and read: build a playlist of music you want to hear and things to read (movies about life''s motivation and upbeat, positive but slow-paced songs)', description_en = 'Choose music, a book, or a movie with a positive message and take time to enjoy it slowly, as a way to shift away from stress.', steps_en = '["1. Build a playlist of positive, slow-paced, or motivating music.","2. Choose a book, article, or film with an uplifting message.","3. Spend 15–30 minutes enjoying it without multitasking.","4. Write down one line or idea that gave you a boost.","5. Repeat this habit at a set time each week."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Slows your heart rate and syncs your brainwaves into an Alpha state","Stimulates the brain''s cortex to release dopamine","Reduces anxiety noticeably more than passive silence"]}'::jsonb where code = '1.47';
update tasks set title_en = 'Be honest with your feelings: don''t try to hide difficult emotions — accept them and face them instead.', description_en = 'Name the emotion you''re feeling, let yourself feel it without judgment, and then choose a safe, healthy way to respond.', steps_en = '["1. Pause and name what you''re feeling right now.","2. Don''t force yourself to feel positive right away.","3. Write: \"I''m feeling... and there''s a reason for it.\"","4. Find a safe way to let the emotion move through you — writing, breathing, crying, or talking.","5. Remind yourself that a difficult emotion doesn''t make you a negative person."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Reshapes the brain (neuroplasticity) in a positive direction","Can reduce depressive symptoms by up to 30% with long-term practice","Boosts natural serotonin production"]}'::jsonb where code = '1.48';
update tasks set title_en = 'Focus on progress: track your progress or setbacks at work, along with the specific events that influenced them. This helps you notice what''s pushing you forward or holding you back, so you can adjust accordingly.', description_en = 'Keep a record of your progress, challenges, and the factors behind them, so you can recognize what''s helping or hindering you and adjust as needed.', steps_en = '["1. Choose an area you want to track, like work, study, health, or emotions.","2. Note your current state using a few simple measures.","3. Write down events that helped you move forward or slowed you down.","4. Find one thing you could adjust in the coming week.","5. Look at your progress over the long run, not just one good or bad day."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Thickens the prefrontal cortex, improving emotional regulation","Shrinks the amygdala, which is linked to anxiety","Improves attention span"]}'::jsonb where code = '1.49';
update tasks set title_en = 'Warm Bath', description_en = 'Soaking in a warm bath after a long day can really help ease your stress.', steps_en = '["1. Prepare water at a comfortably warm temperature.","2. Get in slowly and notice the water touching your skin.","3. Let your shoulders, jaw, and hands relax.","4. Imagine your stress being washed away.","5. Dry off and take a few minutes to rest."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Hydrates brain cells and helps ease tension headaches","Triggers a swallowing reflex that soothes the vagus nerve","An effective grounding mindfulness practice"]}'::jsonb where code = '1.5';
update tasks set title_en = 'Look in the Mirror and Encourage Yourself', description_en = 'Look in the mirror, see your own kind, likeable face, and quietly say to yourself: "I am a good person who keeps trying to grow a little every day, and I deserve good things." It''s a simple, true little mantra.', steps_en = '["1. Stand in front of a mirror somewhere private.","2. Look into your own eyes for a few seconds.","3. Say one genuine, encouraging thing, like: \"Today I tried my best.\"","4. If it feels uncomfortable, just whisper it or write it down instead.","5. Finish with a small smile or a gentle nod to yourself."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s causing anxiety"]}'::jsonb where code = '1.5-b';
update tasks set title_en = 'Journaling', description_en = 'Helps release your emotions by turning negative thoughts into words, easing mental pressure. It builds awareness of what''s causing your stress so you can find ways to deal with it. Write regularly and honestly, and try not to dwell only on the negative — balance it out with positive thoughts too.', steps_en = '["1. Pick a quiet moment in your day.","2. Write down how you''re feeling right now, without editing yourself.","3. Note what happened, your thoughts about it, and how your body reacted.","4. Write down one thing you need or want.","5. Finish with one small action you''ll take to take care of yourself."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s causing anxiety"]}'::jsonb where code = '1.51';
update tasks set title_en = 'Give Yourself Small Gifts', description_en = 'Build the habit of giving yourself small, positive gifts — like letting yourself watch a good movie or enjoy a favorite meal. Don''t be too hard on yourself, even if that treat isn''t always the healthiest choice. These little gifts are rewards along your journey — treat yourself whenever you get past a tough milestone in your life''s story.', steps_en = '["1. Make a list of small, harmless treats — good tea, a break, a book, a nice meal.","2. Choose rewards that fit your budget.","3. Tie the gift to a specific effort — it doesn''t need to be a big achievement.","4. Receive the gift with a sense of gratitude toward yourself.","5. Acknowledge that you deserve to be taken care of."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s causing anxiety"]}'::jsonb where code = '1.52';
update tasks set title_en = 'Lowering Expectations Is Also an Effective Way to Reduce Stress', description_en = 'List the things that stress you out because of high expectations, then lower those expectations or give yourself more time to accomplish them.', steps_en = '["1. Write down one expectation that''s stressing you out.","2. Ask yourself: \"Is this expectation realistic?\"","3. Adjust it into a smaller, gentler goal.","4. Allow yourself to do well enough instead of perfectly.","5. Notice how much lighter you feel when you ease up on yourself."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s causing anxiety"]}'::jsonb where code = '1.6';
update tasks set title_en = 'Saying "No"', description_en = 'Say no, and cut back on things that are unnecessary or don''t suit you.', steps_en = '["1. Recognize a request that''s overloading you.","2. Check your own limits on time, health, and energy.","3. Say \"no\" with a short, polite phrase.","4. Don''t over-explain if you don''t need to.","5. Remind yourself that protecting your limits is a form of self-care."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s causing anxiety"]}'::jsonb where code = '1.7';
update tasks set title_en = 'Turn Off Electronic Devices for 15 Minutes (Digital Detox)', description_en = 'Turn off your phone and computer for a set period of time. The app can lock the screen or simply record your commitment to unplug.', steps_en = '["1. Pick a moment when you can safely step away from your phone.","2. Turn off the screen and notifications, or leave the device in another room.","3. Do something screen-free, like taking a walk, drinking water, breathing, or looking out a window.","4. Notice any restlessness without rushing to pick your phone back up.","5. After 15 minutes, notice how much clearer your head feels."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Reduces social pressure and FOMO-driven stress","Protects your eyes from blue light and supports a healthier body clock","Improves the quality of real-life interactions with people around you"]}'::jsonb where code = '1.8';
update tasks set title_en = 'Delete Unused Phone Apps for a Month (Digital Detox)', description_en = 'Delete junk apps or leave chat groups full of clutter, and stop following accounts that only add noise and negativity to your life.', steps_en = '["1. Open the list of apps on your phone.","2. Identify apps you haven''t used in 30 days or that waste your time.","3. Uninstall them or hide them from your home screen.","4. Keep the apps you need for work, safety, and staying in touch.","5. Notice how much tidier your digital space feels."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Reduces social pressure and FOMO-driven stress","Protects your eyes from blue light and supports a healthier body clock","Improves the quality of real-life interactions with people around you"]}'::jsonb where code = '1.9';
update tasks set title_en = 'Practicing an "Information Fast"', description_en = 'Just as you''re careful about what you eat, be just as careful about the information you consume. Unfollow accounts that make you anxious or angry, and delete news apps from your phone.', steps_en = '["1. Choose a stretch of time to avoid news and social media.","2. Turn off notifications from sources that stress you out.","3. When you feel the urge to check, just notice that urge.","4. Replace it with something concrete, like a walk, a glass of water, or reading a book.","5. After that period, only read what you actually need from sources you trust."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s causing anxiety"]}'::jsonb where code = '2.1';
update tasks set title_en = 'Build a Life Plan for Facing Stress and Setting Life Goals', description_en = 'Spend 5-10 minutes a day building your own life plan, and adjust it daily to match how you''re feeling about your life.', steps_en = '["1. Write down the major sources of stress in your life.","2. Sort them into what you can control and what you can''t.","3. Set long-term goals for your health, work, relationships, and finances.","4. Break each goal down into small monthly or weekly steps.","5. Review and adjust regularly instead of pushing yourself to be perfect."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s causing anxiety"]}'::jsonb where code = '2.1-b';
update tasks set title_en = 'Stay Off Social Media for 10-15 Days (Abandon Social Media)', description_en = 'Staying off social media means less exposure to negative content, helping you recover your good spirits sooner. Social media overloads you with information, pulling your focus away, feeding the fear of missing out (FOMO), and leaving you distracted and stressed.', steps_en = '["1. Let the people you need to reach know you''re taking a break from social media.","2. Delete the apps or log out of your accounts.","3. Line up alternative activities, like reading, exercising, or seeing loved ones.","4. Notice any discomfort or relief you feel in the first few days.","5. After 10-15 days, decide on a healthier way to return."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Reduces social pressure and FOMO-driven stress","Protects your eyes from blue light and supports a healthier body clock","Improves the quality of real-life interactions with people around you"]}'::jsonb where code = '2.11';
update tasks set title_en = 'Do a More Intense Workout (Enough to Break a Sweat)', description_en = 'Do focused, higher-intensity exercise like running, cardio, or yoga.', steps_en = '["1. Pick a workout that suits your fitness level — running, cycling, aerobics, the gym, or dancing.","2. Warm up thoroughly for 5-10 minutes.","3. Push yourself to a sweat while still keeping your breathing under control.","4. Stop right away if you feel chest pain, dizziness, or unusual shortness of breath.","5. Cool down, drink water, and notice the release you feel after moving your body."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Releases endorphins that reduce pain and lift your mood","Improves blood flow to the brain for a clearer mind","Burns off excess adrenaline that causes restlessness"]}'::jsonb where code = '2.12';
update tasks set title_en = 'Communicate More Kindly With Everyone', description_en = 'Adjust the way you text, call, and talk with people to be kinder, clearer, and more respectful, reducing conflict and relationship stress.', steps_en = '["1. Notice how you text, call, email, or talk with people day to day.","2. Identify words that could come across as hurtful, sarcastic, or angry.","3. Before you hit send, reread your message once and soften the wording.","4. Speak clearly and respectfully, without attacking the other person.","5. Notice how conversations start getting warmer responses."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Slows your heart rate and helps your brainwaves settle into a calm Alpha state","Stimulates the brain''s cortex to release dopamine","Reduces anxiety noticeably more than staying silently withdrawn"]}'::jsonb where code = '2.13';
update tasks set title_en = 'Name the Toxic People in Your Life', description_en = 'Recognize the relationships that tend to drain you, note the boundaries you need, and take deliberate steps to limit unhealthy interactions.', steps_en = '["1. Write down the names of people who often leave you exhausted, blamed, manipulated, or disrespected.","2. Note their specific behavior — don''t just label the person.","3. Sort them by how much they affect your mental health.","4. Set the right level of contact for each person.","5. Seek out more safe, positive relationships to balance things out."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Raises oxytocin levels (the bonding hormone that reduces stress)","Reduces feelings of loneliness and depression","Builds motivation and self-esteem through the value of giving"]}'::jsonb where code = '2.14';
update tasks set title_en = 'Cut Back on Smoking and Drinking', description_en = 'Alcohol can bring some positive feelings, but that''s mostly just a cover — mostly it just brings a loss of control, becoming a tool people use to temporarily escape reality.', steps_en = '["1. Pick one specific situation related to cutting back on smoking or drinking that you''d like to change.","2. Write down what''s causing the stress, its effect on you, and the part you can actually control.","3. Propose a safer, more realistic choice, or a necessary boundary for yourself.","4. Take the first small step, and reach out to someone you trust or seek professional support if it''s more than you can handle alone.","5. Note the results and how you feel, and adjust your plan to keep moving in a healthier direction."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s causing anxiety"]}'::jsonb where code = '2.15';
update tasks set title_en = 'Emotion Diary', description_en = 'Write down three emotions you experienced during the day and what caused them.', steps_en = '["1. Open a notes app on your phone or grab paper.","2. Write one line: \"Right now I feel…\"","3. Rate the intensity of the emotion from 1 to 10.","4. Note one possible cause.","5. Note one small action you''ll take in the next 5 minutes."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s causing anxiety"]}'::jsonb where code = '2.16';
update tasks set title_en = 'Origami Challenge', description_en = 'Follow along with a video to fold a simple shape, like a crane or a star.', steps_en = '["1. Get a square piece of paper ready.","2. Choose a simple design, like a crane, a heart, or a boat.","3. Fold slowly, one step at a time.","4. Pay attention to the creases, the color of the paper, and the movement of your hands.","5. Place your finished piece somewhere visible, as a little symbol of patience."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s causing anxiety"]}'::jsonb where code = '2.17';
update tasks set title_en = 'Sky Gazing', description_en = 'Spend 5 minutes looking up at the sky and notice what you see.', steps_en = '["1. Find a safe spot where you can look up at the sky.","2. Notice the colors, clouds, light, or movement.","3. Breathe in slowly and let out a long exhale.","4. Let your thoughts drift by like the clouds.","5. Write down one sentence about the open, spacious feeling this leaves you with."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s causing anxiety"]}'::jsonb where code = '2.18';
update tasks set title_en = 'Sing', description_en = 'Sing anywhere — at karaoke, in the shower, or just relaxing with a couple of drinks with friends and breaking into song.', steps_en = '["1. Choose a song you love.","2. Sing softly or loudly, whatever fits the space you''re in.","3. Focus on your breath and the sound coming out.","4. Don''t judge whether your voice sounds good or not.","5. Notice your body feeling released through the sound."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Slows your heart rate and helps your brainwaves settle into a calm Alpha state","Stimulates the brain''s cortex to release dopamine","Reduces anxiety noticeably more than staying silently withdrawn"]}'::jsonb where code = '2.19';
update tasks set title_en = 'Shift Your Perspective', description_en = 'Challenge gloomy thoughts and replace them with more positive ones by shifting your point of view. Losing a job, for instance, can be reframed as an opportunity for a different job, a fresh and better experience.', steps_en = '["1. Write down the negative thought that''s dominating your mind.","2. Ask yourself: \"Is there another way to look at this?\"","3. Find at least one more positive or neutral possibility.","4. Rewrite the thought in a more balanced, realistic way.","5. Choose one small action that fits this new perspective."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Reshapes neural pathways (neuroplasticity) in a positive direction","Can reduce depressive symptoms by up to 30% with long-term practice","Boosts your body''s natural serotonin production"]}'::jsonb where code = '2.2';
update tasks set title_en = 'Hug', description_en = 'Give someone a hug for about 20 seconds', steps_en = '["1. Choose a loved one, friend, or pet you feel safe hugging.","2. Ask permission if you''re hugging another person.","3. Hug for a few seconds with respect and comfort.","4. Breathe slowly while you hug.","5. If no one is around, hug yourself by wrapping your arms over your shoulders and breathing deeply."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s making you anxious"]}'::jsonb where code = '2.2-b';
update tasks set title_en = 'Shape the Clouds (Cloud Imagination)', description_en = 'Watch the clouds and imagine them turning into fun shapes. Jot down what the experience felt like.', steps_en = '["1. Look up at a cloudy sky.","2. Pick a cloud and imagine what shape it looks like.","3. Let your imagination run free, like when you were a kid.","4. Name 3 shapes you see.","5. Notice the light, playful, creative feeling this brings."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s making you anxious"]}'::jsonb where code = '2.21';
update tasks set title_en = 'Skip screens before bed. Make your sleep space dark, quiet, softly lit, and a comfortable temperature', description_en = 'Step away from electronic devices before bedtime and set up a dark, quiet space at a comfortable temperature so your body can relax.', steps_en = '["1. Pick a time to stop using devices, 30–60 minutes before bed.","2. Dim bright lights and turn off notifications.","3. Set up your bedroom to be dark, quiet, and at a comfortable temperature.","4. Swap screen time for a paper book, soft music, or relaxed breathing.","5. Repeat this routine so your body learns the cues for sleep."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Restores energy to your cells and clears out the brain''s ''waste''","Rebalances stress hormones like cortisol and adrenaline","Boosts memory and problem-solving ability"]}'::jsonb where code = '2.22';
update tasks set title_en = 'Join a Class or Group to Learn a New Instrument', description_en = 'Joining a class or picking up a new instrument helps you feel more connected to life and discover new passions.', steps_en = '["1. Choose an instrument or class that sparks your curiosity.","2. Find a class suited to beginners.","3. Sign up for a trial session or join a small group.","4. Learn with a spirit of exploration — you don''t need to be good right away.","5. Notice the joy of your brain learning something new."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Slows your heart rate and syncs your brainwaves into a calm Alpha state","Stimulates the brain''s cortex to release dopamine","Significantly reduces anxiety compared to passive silence"]}'::jsonb where code = '2.23';
update tasks set title_en = 'Rediscover an Old Passion and Give It New Life', description_en = 'When work and life pile on the stress, take time to rediscover an old passion of yours. When you''re doing that, you''re working with lightness and joy.', steps_en = '["1. Write down things that used to make you happy.","2. Pick one old passion that''s still doable now.","3. Start again in a very small way, without comparing to how it used to be.","4. Add something new to spark fresh interest.","5. Note how it feels to reconnect with a part of your past self."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s making you anxious"]}'::jsonb where code = '2.24';
update tasks set title_en = 'Make a Plan', description_en = 'If life feels stuck and nothing else has eased your stress, break your plan down into small steps and small goals you can tackle one at a time. Making a plan is a positive way to reduce stress.', steps_en = '["1. Write down the problem or goal that''s making you feel stuck.","2. Break it into small, doable steps.","3. Pick the simplest first step.","4. Set a specific time to do it.","5. Once it''s done, mark it complete and adjust your plan if needed."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s making you anxious"]}'::jsonb where code = '2.25';
update tasks set title_en = 'Build or Strengthen Positive Relationships: Look for chances to work with colleagues who energize you, and steer clear of people who drain you. Build connection by sharing good news or expressing gratitude.', description_en = 'Actively nurture positive relationships by sharing good news, expressing gratitude, and spending time with people who energize you.', steps_en = '["1. Identify the people who give you energy.","2. Reach out to thank them or share good news with them.","3. Make time for healthy relationships.","4. Reduce contact with people who tend to drain you, where possible.","5. Notice how uplifted you feel after a positive interaction."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Reshapes the brain''s neural pathways in a positive direction (neuroplasticity)","Reduces symptoms of depression by up to 30% with long-term practice","Boosts your body''s natural serotonin production"]}'::jsonb where code = '2.26';
update tasks set title_en = 'Treat People Well: Practice courtesy and care for others, starting with your own family.', description_en = 'Practice speaking courteously, listening, and showing care in your closest family interactions to build a sense of safe connection.', steps_en = '["1. Pick a situation at home or work to practice with.","2. Pause before reacting.","3. Speak politely, clearly, and without putting anyone down.","4. Care about the other person''s feelings while still holding your own boundaries.","5. Remember that kindness can start with the smallest gesture."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Raises oxytocin levels (the bonding hormone that lowers stress)","Reduces feelings of loneliness and depression","Builds motivation and self-esteem through the value of giving"]}'::jsonb where code = '2.27';
update tasks set title_en = '5-10 Minute Meditation (Meditation Task)', description_en = 'Guide yourself through meditation with a guided voice or ambient sound. You can track your breath and meditation time. Sit up straight (or lie down flat), keep your neck lifted (to take in as much oxygen as possible), focus on your breath, and let thoughts come and go — even the unpleasant ones, letting discomfort arrive and then gently pass, leaving only ease behind.', steps_en = '["1. Sit or lie down in a comfortable position.","2. Bring your attention to your breath.","3. When a thought appears, notice it, then return to your breath.","4. Don''t try to force your mind to go blank.","5. Close by saying to yourself: \"I allow myself to be here.\""]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Thickens the prefrontal cortex, improving emotional regulation","Shrinks the amygdala, which is linked to anxiety","Improves your attention span"]}'::jsonb where code = '2.3';
update tasks set title_en = 'Build the Habit of Sitting and Standing Tall', description_en = 'Practice sitting and walking with good posture to take in more oxygen and ease the pressure on your spine.', steps_en = '["1. Notice your current posture.","2. Gently draw your shoulders back and relax your neck.","3. Keep your back comfortably straight, without stiffening up.","4. When walking, place each step firmly.","5. Notice any shift in how confident and alert you feel."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Raises oxytocin levels (the bonding hormone that lowers stress)","Reduces feelings of loneliness and depression","Builds motivation and self-esteem through the value of giving"]}'::jsonb where code = '2.4';
update tasks set title_en = 'Box Breathing Exercise', description_en = 'Breathe in for 4 seconds, hold for 4 seconds, breathe out for 4 seconds, then hold again for 4 seconds. Repeat for 5 rounds.', steps_en = '["1. Breathe in for 4 seconds.","2. Hold your breath for 4 seconds.","3. Breathe out for 4 seconds.","4. Hold again for 4 seconds after breathing out.","5. Repeat for 5 rounds, and stop if it feels uncomfortable."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Activates the parasympathetic nervous system (rest and digest)","Slows your heart rate and lowers blood pressure right away","Boosts oxygen to the brain, sharpening focus"]}'::jsonb where code = '2.5';
update tasks set title_en = 'Set a Small Daily Goal and Win It (Micro-goal Setting)', description_en = 'Choose one small goal and complete it today — like tidying your desk or reading 10 pages of a book.', steps_en = '["1. Choose a small, clear goal you can finish today.","2. Turn it into a specific action.","3. Set a start time.","4. Complete the goal, even at the most minimal level.","5. Give yourself credit for this small win."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s making you anxious"]}'::jsonb where code = '2.6';
update tasks set title_en = 'Take a Scenic Walk in Nature (Mindful Walk Quest)', description_en = 'Walk for at least 30 minutes, and take a photo of the most beautiful scene you see, or write down how you feel afterward. Immersing yourself in nature, touching it, taking it in with all your senses helps reduce stress. If you can, try walking barefoot.', steps_en = '["1. Choose a safe place to walk, like a park, a quiet street, or a garden.","2. Walk slower than usual.","3. Notice the trees, the light, the wind, the scents, and the sounds.","4. When your mind wanders, bring your attention back to your steps.","5. Finish with a deep breath and note the most beautiful thing you saw."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Releases endorphins that ease pain and lift your mood","Improves blood flow to the brain for more clarity","Burns off excess adrenaline that causes restlessness"]}'::jsonb where code = '2.7';
update tasks set title_en = 'Create Your Own Emotion Anchor', description_en = 'Create an emotional anchor for yourself — it could be a child''s laughter, a loved one, someone who cares for you and whom you care for. Think of them and the happy memories you''ve shared with them.', steps_en = '["1. Choose a symbol, small object, phrase, or gesture that makes you feel safe.","2. Link it to a calm state by breathing deeply whenever you touch it or think of it.","3. Repeat this a few times while you''re already feeling okay.","4. When stressed, use your anchor to remind your body to return to a sense of safety.","5. Strengthen your anchor each day with a short practice."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s making you anxious"]}'::jsonb where code = '2.8';
update tasks set title_en = 'Create a Happiness Box', description_en = 'Make yourself a happiness box filled with keepsakes that motivate you — a gift from a friend, a memento from your mother, or objects tied to happy memories.', steps_en = '["1. Get a small box or a digital folder ready.","2. Fill it with photos, notes, quotes, keepsakes, or a list of things you''re grateful for.","3. Add anything that brings a feeling of warmth and hope.","4. When you''re feeling sad or stressed, open it and look through each item slowly.","5. Keep adding to your happiness box whenever you make a new good memory."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s making you anxious"]}'::jsonb where code = '2.9';
update tasks set title_en = 'Build a Strong Mental Filter', description_en = 'When you come across new information, ask yourself: Does this actually relate to my life? Is there anything I can do to change it? Will it still matter in a week? A year? Is it trying to manipulate my emotions?', steps_en = '["1. When new information comes your way, pause before reacting.","2. Ask: \"Does this really relate to me?\"","3. Ask: \"What part of this can I actually control?\"","4. Ask: \"Will this still matter a week from now?\"","5. Keep only what''s useful and let go of the noise."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Slows your heart rate and syncs your brainwaves into a calm Alpha state","Stimulates the brain''s cortex to release dopamine","Significantly reduces anxiety compared to passive silence"]}'::jsonb where code = '3.1';
update tasks set title_en = 'Do Something Unexpectedly Kind (Random Act of Kindness Game)', description_en = 'Do something unexpectedly kind for someone else — buy a coworker a coffee, or help out a neighbor.', steps_en = '["1. Pick a small act of kindness that doesn''t need to be noticed.","2. Do it for someone else — a kind word, letting someone go ahead, or a small favor.","3. Don''t expect anything in return.","4. Notice how it feels to actively create something good.","5. Write down that act of kindness at the end of the day."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s making you anxious"]}'::jsonb where code = '3.1-b';
update tasks set title_en = 'Fully Unplug from Electronic Devices for a Set Time Each Day', description_en = 'Stepping away from all electronic devices helps you regain balance, ease tension and fatigue, and enjoy life more fully.', steps_en = '["1. Pick a fixed block of time to go device-free.","2. Let anyone who might need to reach you know beforehand, if needed.","3. Keep your phone out of easy reach.","4. Replace screen time with reading, walking, cooking, or conversation.","5. Keep it up for at least 3 days to notice the change."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Eases social pressure and FOMO-driven stress","Protects your eyes from blue light and improves your body clock","Improves the quality of your real-world interactions with people around you"]}'::jsonb where code = '3.11';
update tasks set title_en = 'Have a Clear Vision', description_en = 'for your life, and a plan to get there. Many capable people don''t know what they''re doing with their lives, and feel useless and powerless. Having a clear vision brings purpose and meaning.', steps_en = '["1. Write down the life you want to have 1–3 years from now.","2. Choose 3 key areas, like health, work, and relationships.","3. Write specific but flexible goals for each area.","4. Break each goal into small steps for this month.","5. Revisit your vision whenever you feel lost."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s making you anxious"]}'::jsonb where code = '3.12';
update tasks set title_en = 'Accept Reality: Steadily accept reality, even when it''s hard. Go with the natural flow of things.', description_en = 'See things as they truly are, tell apart what you can and can''t change, so you can ease resistance and act with a calmer mind.', steps_en = '["1. Name the difficult situation you''re facing.","2. Tell apart what you wish were true from what''s actually happening.","3. Say: \"I don''t like this, but I accept that it''s happening.\"","4. Find one action that fits the reality you''re in right now.","5. Remind yourself that accepting something doesn''t mean giving up."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Reshapes the brain''s neural pathways in a positive direction (neuroplasticity)","Reduces symptoms of depression by up to 30% with long-term practice","Boosts your body''s natural serotonin production"]}'::jsonb where code = '3.13';
update tasks set title_en = 'This means they don''t avoid or deny difficult situations, but face them head-on. This ability helps them get through adversity and bounce back from setbacks', description_en = 'Face a difficulty one step at a time, identify a small thing you can do right now, and notice your own resilience each time you get through an obstacle.', steps_en = '["1. Prepare a drink or snack suited to this exercise, taking it slow and mindful.","2. Notice its color, temperature, smell, and how it feels in your hand before you start.","3. Take small sips or bites, paying attention to the taste and how your body responds.","4. Keep going slowly, stop once you''ve had enough, and avoid using this as a way to avoid your feelings.","5. Notice how your body feels, your mood, and any healthy choice you''d like to keep making."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Hydrates brain cells, easing stress-related headaches","Activates the swallowing reflex, which helps soothe the vagus nerve","An effective mindful grounding practice"]}'::jsonb where code = '3.14';
update tasks set title_en = 'Forgiving an Enemy', description_en = 'When we hold on to resentment, anger, or guilt, these negative emotions build up and create stress. Forgiveness helps release these feelings, easing your mental load and bringing a sense of relief.', steps_en = '["1. Write down the person or situation you still feel resentment toward.","2. Acknowledge that your hurt is real.","3. Recognize that forgiving is different from excusing wrongdoing or returning to a harmful relationship.","4. Write one sentence that lets go of some of the weight, for your own sake.","5. If you can''t forgive yet, start simply by not letting them take up all the space in your mind."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s triggering your anxiety"]}'::jsonb where code = '3.15';
update tasks set title_en = 'Play with an Animal (Pet Bonding Task)', description_en = 'If you have a pet, spend 10 minutes playing with them and notice the positive feelings afterward.', steps_en = '["1. Choose an animal you feel safe and familiar with.","2. Watch how they breathe, move, or rest.","3. Interact gently — pet them, feed them, or play together.","4. Respect the animal''s own limits.","5. Notice the softening you feel in your body."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s triggering your anxiety"]}'::jsonb where code = '3.16';
update tasks set title_en = 'Play chess, learn to play chess, or solve puzzles (even a brain game on your phone or computer works)', description_en = 'Playing or learning chess keeps your mind focused while gently pulling it away from stress and fatigue.', steps_en = '["1. Choose a mind game that matches your level — chess, crosswords, sudoku, or a puzzle app.","2. Set aside 10 to 30 minutes to play.","3. Focus on the rules and the move in front of you right now.","4. Don''t worry about winning or losing.","5. Notice how your mind shifts away from anxious thoughts."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s triggering your anxiety"]}'::jsonb where code = '3.17';
update tasks set title_en = 'Draw Your Feelings (Expressive Art Challenge)', description_en = 'Draw a picture that shows how you''re feeling right now — it doesn''t need to look good.', steps_en = '["1. Get some paper and colored pens, or a simple drawing tool.","2. Pick one feeling that''s present for you right now.","3. Draw that feeling using colors, shapes, or lines.","4. Don''t judge whether it looks good or bad.","5. Write one sentence describing your drawing once you''re done."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s triggering your anxiety"]}'::jsonb where code = '3.19';
update tasks set title_en = 'Talk with Someone You Trust (Connect with a Friend Challenge)', description_en = 'Call or meet in person with someone you trust, and notice how you feel after the conversation.', steps_en = '["1. Pick a friend you feel safe enough to open up to.","2. Send a message or call to ask for a few minutes of their time.","3. Let them know you need to be heard more than you need advice or judgment.","4. Share as much as feels comfortable to you.","5. Thank them, and notice how you feel after the conversation."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Raises oxytocin levels (the bonding hormone that lowers stress)","Reduces feelings of loneliness and low mood","Builds motivation and self-worth through the value of giving"]}'::jsonb where code = '3.2';
update tasks set title_en = 'Play the "Silence Challenge"', description_en = 'Challenge yourself to sit quietly and not speak for 10-15 minutes.', steps_en = '["1. Choose a length of silence, from 5 to 15 minutes.","2. Turn down sounds and notifications around you.","3. Sit still, walk slowly, or do something gentle in silence.","4. When a thought appears, simply notice it and return to your breath.","5. Finish by writing down what you noticed."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s triggering your anxiety"]}'::jsonb where code = '3.2-b';
update tasks set title_en = 'Grow or Care for a Plant (Plant Care Task)', description_en = 'Water a plant, trim its leaves, and notice the sense of calm it brings.', steps_en = '["1. Choose a small plant or an easy-to-care-for potted plant.","2. Water it, wipe its leaves, change the soil, or move it somewhere with good light.","3. Notice the color of the leaves, the moisture in the soil, and the plant''s vitality.","4. Take your time, treating this like a gentle ritual of care.","5. Notice how caring for the plant connects to caring for yourself."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s triggering your anxiety"]}'::jsonb where code = '3.21';
update tasks set title_en = 'Give Your Full Presence to Whatever Activity You Choose', description_en = 'Choose a meaningful activity and give it your complete focus for a short while to create a sense of flow and ease stressful thinking.', steps_en = '["1. Choose a healthy activity like cooking, reading, studying, playing music, or tidying up.","2. Turn off distractions around you.","3. Give the activity your full attention for a short stretch of time.","4. When your mind wanders, gently bring it back.","5. Notice the feeling of being fully present in the moment."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s triggering your anxiety"]}'::jsonb where code = '3.3';
update tasks set title_en = 'Give Yourself More Time: Let yourself have more time to finish your plans, and you''ll feel more at ease and relaxed', description_en = 'Extend a deadline where reasonable, break your plan into smaller steps, and allow yourself rest, so you don''t feel pressured to finish too quickly.', steps_en = '["1. Identify the plan that''s putting pressure on you.","2. Check which deadlines are truly required and which ones you''ve set for yourself.","3. Extend the deadline or break the plan into smaller steps if you can.","4. Let the people involved know clearly, if needed.","5. Remind yourself that going slower doesn''t mean you''re failing."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s triggering your anxiety"]}'::jsonb where code = '3.4';
update tasks set title_en = 'Take Part in a Charitable Activity (Kindness Challenge) - Level 2 Social Interaction', description_en = 'Take part in a small charitable activity, like giving a gift to someone in need or helping others. This builds level 2 social interaction.', steps_en = '["1. Choose a charitable activity that fits your energy and time.","2. Find a trustworthy organization or group.","3. Contribute your effort, items, skills, or simply your presence.","4. Stay respectful toward the people you''re supporting.","5. Write down how meaningful it felt afterward."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Raises oxytocin levels (the bonding hormone that lowers stress)","Reduces feelings of loneliness and low mood","Builds motivation and self-worth through the value of giving"]}'::jsonb where code = '3.5';
update tasks set title_en = 'Visit an Orphanage or Hospital (Community Engagement Task)', description_en = 'Consider visiting a community organization, hospital, or orphanage to make a meaningful connection.', steps_en = '["1. Contact the place ahead of time to ask about visiting rules and how you can help.","2. Prepare a suitable gift or activity, taking care not to be a burden.","3. Arrive with a respectful attitude, and avoid taking photos without asking.","4. Listen and interact gently.","5. Afterward, reflect on what you learned about gratitude and connection."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s triggering your anxiety"]}'::jsonb where code = '3.6';
update tasks set title_en = 'Level 2 Social Interaction', description_en = 'Build closer relationships with loved ones, family, or trusted colleagues — people you can share views and perspectives with, help each other, and open up to more quickly. Keep nurturing these relationships so they stay strong.', steps_en = '["1. Choose someone you trust for a deeper conversation than level 1.","2. Invite them for coffee, a walk, or a 15-30 minute call.","3. Share something genuine, without pushing yourself too far.","4. Listen closely to their story in return.","5. Notice how connected you feel after meeting."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s triggering your anxiety"]}'::jsonb where code = '3.7';
update tasks set title_en = 'Keep an Emotional Journal (Emotional Journaling)', description_en = 'Write down your feelings each day for a week, and reflect on the positive progress you notice by the end.', steps_en = '["1. Note the date, time, and the feeling that stands out most.","2. Rate the intensity of that feeling from 1 to 10.","3. Write about the event or thought connected to it.","4. Note any physical response, like a headache, tense shoulders, or a racing heart.","5. End with one need or one act of self-care you''d like to take."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s triggering your anxiety"]}'::jsonb where code = '3.8';
update tasks set title_en = 'Write a Letter to Your Future Self', description_en = 'Write a warm, encouraging letter addressed to your future self.', steps_en = '["1. Choose a point in time — 3 months, 6 months, or a year from now.","2. Write to your future self the way you''d write to someone you love.","3. Tell them about what you''re going through now and what you''re working toward.","4. Include a message of encouragement, hope, or a promise to yourself.","5. Save the letter and set a reminder to read it again later."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s triggering your anxiety"]}'::jsonb where code = '3.9';
update tasks set title_en = 'Host a Positive Sharing Get-Together (Positive Sharing Event)', description_en = 'Organize an online meetup with friends to share the good things happening in your lives.', steps_en = '["1. Gather a small group of 2-5 friends you feel safe sharing with.","2. Agree on a time, place, or online format together.","3. Pick an uplifting theme, like \"a good thing this week,\" \"something I''m grateful for,\" or \"something I got through.\"","4. Take turns sharing, without interrupting or judging.","5. End by naming one positive feeling you noticed after the gathering."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Reshapes neural pathways (neuroplasticity) in a positive direction","Can reduce symptoms of low mood by up to 30% with long-term practice","Boosts your body''s natural serotonin production"]}'::jsonb where code = '4.1';
update tasks set title_en = 'Give Back to Your Community (Volunteer Challenge) - Level 3 Social Interaction', description_en = 'Take part in a local volunteer activity — picking up litter, distributing gifts to those in need, or helping people facing hardship. Through this, you may notice how fortunate you are compared to others who live with the loss of a limb, their voice, or other disabilities.', steps_en = '["1. Choose a community activity that matches your energy, like cleaning up litter, helping in a classroom, donating, or supporting someone in need.","2. Decide how much time and energy you can give.","3. Take part in a spirit of giving, without pushing yourself too hard.","4. Treat others taking part with kindness and courtesy.","5. Write down how meaningful it felt once you''re done."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Raises oxytocin levels (the bonding hormone that lowers stress)","Reduces feelings of loneliness and low mood","Builds motivation and self-worth through the value of giving"]}'::jsonb where code = '4.2';
update tasks set title_en = 'Teach a Skill to Someone Else (Teaching Task)', description_en = 'Share a simple skill — like cooking or a craft — with a friend or family member.', steps_en = '["1. Pick a small skill you know, like cooking, a language, using a computer, or relaxed breathing.","2. Find someone who wants to learn or could use the help.","3. Break the skill down into simple steps.","4. Teach at a gentle pace, encouraging rather than criticizing.","5. Notice the confidence and connection you feel after helping someone learn something new."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Raises oxytocin levels (the bonding hormone that lowers stress)","Reduces feelings of loneliness and low mood","Builds motivation and self-worth through the value of giving"]}'::jsonb where code = '4.3';
update tasks set title_en = 'Step Away from Your Current Environment', description_en = 'Ease the overload from noise, crowds, conflict, or an uncomfortable environment.', steps_en = '["1. Notice that your current environment is overwhelming you.","2. Leave that spot safely, if you can.","3. Go somewhere calmer, like a hallway, a yard, another room, or a quiet cafe.","4. Breathe slowly and take in your surroundings.","5. Only go back once you feel calmer."]'::jsonb, safety_notes_en = '["If you''re driving or somewhere unsafe, first focus on finding a safe place to stop.","Don''t isolate yourself for too long if you''re in a serious crisis — try to reach out and connect with someone who can support you."]'::jsonb, metadata_en = '{"benefits":["Slows your heart rate and syncs your brainwaves toward a calmer Alpha state","Stimulates the cortex to release dopamine","Noticeably reduces anxiety compared to passive silence"]}'::jsonb where code = 'E1';
update tasks set title_en = 'Let Yourself Cry', description_en = 'If crying eases your stress and worry, let yourself cry over your losses — cry until your heart feels lighter.', steps_en = '["1. Find a private, safe space.","2. Let yourself cry if the tears come.","3. Don''t call yourself weak for it.","4. Once you''ve cried, drink some water and breathe slowly.","5. If your feelings become overwhelming or you have thoughts of harming yourself, reach out to someone you trust or an emergency support line."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Releases feel-good hormones (endorphins/dopamine)","Helps shift your attention away from what''s triggering your anxiety"]}'::jsonb where code = 'E10';
update tasks set title_en = 'The Truth', description_en = 'Say a truth you''ve wanted to say to someone for a long time.', steps_en = '["1. Write down a thought that''s hurting or worrying you.","2. Ask yourself: \"What do I actually know for certain?\"","3. Then ask: \"What''s just an assumption or a fear?\"","4. Rewrite it as a more balanced sentence, grounded in evidence.","5. Choose one small action based on the truth, not on panic."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps redirect attention away from what''s triggering your anxiety"]}'::jsonb where code = 'E11';
update tasks set title_en = 'Listen to Instrumental Music (Instrumental Music Quest)', description_en = 'Offers a list of gentle music (piano or nature sounds). You complete the task by listening for at least 5 minutes.', steps_en = '["1. Choose a gentle instrumental track.","2. Sit or lie down in a comfortable position.","3. Listen to the whole track without scrolling on your phone.","4. Let the sound guide your breathing into a slower rhythm.","5. Notice how you feel once it''s finished."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Slows your heart rate and syncs your brainwaves into a calmer Alpha state","Stimulates the brain''s cortex to release dopamine","Reduces anxiety significantly more than passive silence"]}'::jsonb where code = 'E12';
update tasks set title_en = 'Drink a Glass of Water Slowly (Mindful Drinking Game)', description_en = 'Drink a full glass of water over 3-5 minutes, paying attention to the taste and sensation with every sip.', steps_en = '["1. Prepare a glass of water.","2. Notice its color, clarity, and surface.","3. Take small sips, one at a time.","4. Feel the temperature and movement of the water inside you.","5. Remind yourself: \"I''m taking care of my body with something this simple.\""]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Hydrates brain cells, easing tension headaches","Triggers the swallowing reflex, which helps calm the vagus nerve","An effective, simple grounding mindfulness practice"]}'::jsonb where code = 'E13';
update tasks set title_en = 'The Smile Exercise (Smile for 1 Minute Challenge)', description_en = 'Smile continuously for 1 minute. The app can turn on the camera to confirm the challenge is complete. Note: this isn''t for moments of deep sadness — when grief is heavy, crying is often more helpful than smiling.', steps_en = '["1. Choose a moment and a space that feels right for the \"Smile Exercise.\"","2. Get anything you need ready and set aside distractions for now.","3. Move through it slowly, at your own pace, staying focused on the present moment.","4. Notice your breathing and body sensations, and adjust or stop if anything feels uncomfortable.","5. Notice how you feel afterward, and one helpful thing you''d like to try again next time."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Facial feedback effect: your brain reads the simulated smile as happiness and releases a small dose of serotonin","Effectively lowers heart rate after stress"]}'::jsonb where code = 'E14';
update tasks set title_en = 'Stress Ball**', description_en = 'A hands-on technique for releasing tension. Squeeze a stress ball in your non-dominant hand while picturing the tension melting away.', steps_en = '["1. Hold a soft ball or a safe squeeze toy.","2. Squeeze gently for 3-5 seconds.","3. Release and relax your hand for 3-5 seconds.","4. Repeat 10-15 times, breathing slowly as you go.","5. Notice the tension moving out of your body."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps redirect attention away from what''s triggering your anxiety"]}'::jsonb where code = 'E15';
update tasks set title_en = 'Rubber Band Technique', description_en = 'Wear a rubber band around your wrist and give it a gentle snap whenever a negative thought comes up.', steps_en = '["1. Wear a soft rubber band on your wrist, as long as it doesn''t hurt or irritate your skin.","2. When you notice a recurring negative thought, snap it gently and let go softly.","3. Use that sensation as a cue to come back to the present — not as a way to punish yourself.","4. Take a deep breath and say: \"Stop. Come back to now.\"","5. Shift into a healthy action, like drinking water, writing the thought down, or going for a walk."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps redirect attention away from what''s triggering your anxiety"]}'::jsonb where code = 'E16';
update tasks set title_en = 'The Small Wand Exercise', description_en = 'A way to soothe your senses. Hold a pencil or small stick in one hand. Slowly and carefully, trace the outline of your other hand with it. Let the pencil or stick glide over your fingers, palm, the back of your hand, around and in and out of your hand, and around your wrist. Notice if any area of your hand or wrist seems to need more attention, and gently trace and stroke that area more slowly. After a few minutes, set the pencil or stick down. Notice how that hand feels now. How does it compare to your other hand? Now switch hands and hold the pencil or stick in the other one. Trace the outline of your other hand again, very slowly.', steps_en = '["1. Get a small stick, pen, or other safe object you can hold.","2. Hold it in your hand and notice its shape, weight, and texture.","3. Move it slowly between your fingers.","4. Focus on the sensation of touch to bring your mind back to the present.","5. Finish by setting it down and taking one long exhale."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps redirect attention away from what''s triggering your anxiety"]}'::jsonb where code = 'E17';
update tasks set title_en = 'The Fifteen Things Exercise', description_en = 'Start by finding five things around you that you can see. Say out loud what they are, using specific words to describe what you''re looking at. Next, find four sounds around you that you can hear. Say out loud what they are, using as many specific words as you can to describe each sound. Find three things around you that you can touch or are already touching. Say out loud what they are, using specific words to describe the touch. Find two things around you that you can smell. Say out loud what they are. Find one thing around you that you can taste. Say out loud what it is.', steps_en = '["1. Look around the space you''re in right now.","2. Name 15 things you can see.","3. Briefly describe the color or shape of each one.","4. If you still feel tense, keep going by naming 10 sounds or 5 body sensations.","5. Notice your mind settling further into the present."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps redirect attention away from what''s triggering your anxiety"]}'::jsonb where code = 'E18';
update tasks set title_en = 'Play With a Child or Talk With a Wise Elder', description_en = 'Children bring a sense of innocence and bright energy, so playing with a child is a way to bring your mind back to a happier place. A wise elder is someone whose advice we can turn to.', steps_en = '["1. Choose someone you feel safe with in your family or community.","2. If it''s a child, play a simple, fun game together.","3. If it''s an older person, listen to their story or their advice.","4. Engage with respect and full presence.","5. Notice the sense of connection between generations."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Raises oxytocin levels (the bonding hormone that reduces stress)","Reduces feelings of loneliness and depression","Builds motivation and self-esteem through the value of giving"]}'::jsonb where code = 'E19';
update tasks set title_en = 'Deep Breathing (Deep Breathing Game)', description_en = 'Guides you through slow inhales and exhales for 1-2 minutes, with a visual bubble that grows as you breathe in and shrinks as you breathe out. Sit with your back straight in a chair. Breathe deeply and slowly. Lift your chin slightly to open up your breathing.', steps_en = '["1. Sit up straight or lie down comfortably.","2. Breathe in through your nose for 4 seconds.","3. Hold gently for 1-2 seconds if that feels comfortable.","4. Breathe out slowly through your mouth for 6 seconds.","5. Repeat for 5-10 rounds and notice your body settling."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Activates your parasympathetic nervous system (rest and digest)","Slows your heart rate and lowers blood pressure right away","Boosts oxygen to your brain, improving focus"]}'::jsonb where code = 'E2';
update tasks set title_en = '"Stop, Drop, and Breathe"', description_en = 'Stop when a negative thought arises, focus on your breath, and replace it with positive affirmations.', steps_en = '["1. Stop: Pause whatever you''re doing for a few seconds.","2. Drop: Relax your shoulders, jaw, and hands, and let your body slow down.","3. Breathe: Inhale slowly and exhale for a long breath out.","4. Look around and name 3 things you can see.","5. Only continue once you feel less on autopilot."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Activates your parasympathetic nervous system (rest and digest)","Slows your heart rate and lowers blood pressure right away","Boosts oxygen to your brain, improving focus"]}'::jsonb where code = 'E3';
update tasks set title_en = 'Slow Down Your Speech', description_en = 'Notice your own voice and deliberately slow your speech down. Speaking more slowly naturally leads to deeper, steadier breathing. Slow, steady breathing helps activate your parasympathetic nervous system (rest and digest), so your body relaxes and your heart rate settles. This is a way of regulating your breath through your voice.', steps_en = '["1. Notice when you''re speaking fast because you''re stressed.","2. Pause for a beat before you respond.","3. Speak in short, clear sentences.","4. Breathe between sentences.","5. Notice the conversation becoming calmer."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Strengthens the prefrontal cortex, improving emotional regulation","Shrinks the amygdala''s reactivity, which is linked to anxiety","Improves attention span"]}'::jsonb where code = 'E4';
update tasks set title_en = 'Splash Your Face With Cold Water', description_en = 'Washing your face with cold water gives you a refreshing, alert feeling, and in that moment your stress eases.', steps_en = '["1. Get some cool or moderately cold water ready.","2. Wash your face slowly for 20-30 seconds.","3. Notice the temperature of the water on your skin.","4. Pat your face dry gently.","5. Take a deep breath and check in on your stress level afterward."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Hydrates brain cells, easing tension headaches","Triggers the swallowing reflex, which helps calm the vagus nerve","An effective, simple grounding mindfulness practice"]}'::jsonb where code = 'E5';
update tasks set title_en = 'Forgive Yourself', description_en = 'When we hold onto resentment, anger, or guilt, these negative emotions build up and create stress. Forgiveness helps release them, lightening the weight on your mind and bringing a sense of relief.', steps_en = '["1. Write down what you''ve been blaming yourself for.","2. Acknowledge your responsibility if there is any, without attacking yourself.","3. Write this sentence: \"I did the best I could with what I knew at the time.\"","4. Identify one small lesson or corrective action.","5. Give yourself permission to keep living and growing."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps redirect attention away from what''s triggering your anxiety"]}'::jsonb where code = 'E6';
update tasks set title_en = 'Stop Comparing Yourself', description_en = 'Stop comparing yourself to others — their achievements, what they have, what they''ve had. Comparing less and expecting less will help you stay in a state of contentment, happiness, and ease.', steps_en = '["1. Notice the moment you start comparing yourself to someone else.","2. Step away from the trigger, like social media or a conversation.","3. Write down one thing you have or have worked hard for.","4. Remind yourself that everyone starts from a different place.","5. Return your focus to one small goal of your own."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Lowers cortisol levels, helping your nervous system relax","Produces feel-good hormones (endorphins/dopamine)","Helps redirect attention away from what''s triggering your anxiety"]}'::jsonb where code = 'E7';
update tasks set title_en = 'Take a Break', description_en = 'Give yourself a quiet moment, apart from whatever is causing your stress. Create a bit of space for yourself so you can settle down — for example, taking a day or two off, going for a walk, or having a short nap.', steps_en = '["1. Stop working for 5-20 minutes.","2. Step away from the screen or change your position.","3. Drink some water, breathe slowly, or just lie still.","4. Don''t use this break to criticize yourself.","5. Return to your work with the smallest possible step."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Restores energy to your cells and clears out mental \"waste\"","Rebalances stress hormones like cortisol and adrenaline","Improves memory and problem-solving ability"]}'::jsonb where code = 'E8';
update tasks set title_en = 'Hold a Warm Cup and Notice How It Feels (Warm Cup Challenge)', description_en = 'Hold a cup of warm water and focus on the warmth in your hands for 3 minutes.', steps_en = '["1. Prepare a safe cup of warm water.","2. Hold the cup with both hands.","3. Feel the warmth spreading into your palms.","4. Breathe slowly, and take small sips if you''d like.","5. Let the warmth remind your body that you are safe."]'::jsonb, safety_notes_en = '[]'::jsonb, metadata_en = '{"benefits":["Hydrates brain cells, easing tension headaches","Triggers the swallowing reflex, which helps calm the vagus nerve","An effective, simple grounding mindfulness practice"]}'::jsonb where code = 'E9';
